"""The README demo is generated by scripts/demo.py; keep it runnable and truthful."""

from __future__ import annotations

import runpy
from pathlib import Path

DEMO = Path(__file__).resolve().parents[1] / "scripts" / "demo.py"


def test_demo_shows_preview_apply_conflict_and_read_only_mcp(capsys, monkeypatch, tmp_path) -> None:
    monkeypatch.chdir(tmp_path)
    runpy.run_path(str(DEMO), run_name="__main__")
    out = capsys.readouterr().out
    assert "$ benchling-tools entry inspect etr_abc123 --env demo" in out
    assert "$ benchling-tools --env" not in out
    assert "remote writes so far: 0" in out
    assert "remote writes in total: 1" in out
    assert out.count("[exit 5]") == 2
    assert "Entry version changed after the plan was created" in out
    assert "Plan has already been applied or attempted" in out
    assert "MCP writes are disabled for demo" in out
